import React, { useState } from 'react';
import './MenuItems.css';

const MenuItems = ({ items, onItemSelect }) => {
  const [expandedItem, setExpandedItem] = useState(null);
  const [selectedOptions, setSelectedOptions] = useState({});

  const formatPrice = (price) => `RM ${price.toFixed(2)}`;

  // 메뉴별 옵션 정의
  const getItemOptions = (itemId) => {
    const optionsMap = {
      1: { // Bulgogi Rice Bowl
        size: [
          { id: 'M', name: 'Regular', price: 0 },
          { id: 'L', name: 'Large', price: 3.00 }
        ],
        spice: [
          { id: 'mild', name: '보통', price: 0 },
          { id: 'hot', name: '매움', price: 0 }
        ],
        toppings: [
          { id: 'cheese', name: 'Extra Cheese', price: 2.00 },
          { id: 'egg', name: 'Fried Egg', price: 1.50 }
        ]
      },
      2: { // Kimchi Fried Rice
        size: [
          { id: 'M', name: 'Regular', price: 0 },
          { id: 'L', name: 'Large', price: 2.50 }
        ],
        spice: [
          { id: 'mild', name: '보통', price: 0 },
          { id: 'hot', name: '매움', price: 0 },
          { id: 'very-hot', name: '아주매움', price: 0 }
        ]
      },
      3: { // Korean BBQ Set
        size: [
          { id: 'M', name: 'Regular', price: 0 },
          { id: 'L', name: 'Large', price: 4.00 }
        ]
      }
    };
    return optionsMap[itemId] || null;
  };

  const handleToggleOptions = (itemId) => {
    if (expandedItem === itemId) {
      setExpandedItem(null);
    } else {
      setExpandedItem(itemId);
      // 기본 옵션 설정
      if (!selectedOptions[itemId]) {
        const options = getItemOptions(itemId);
        const defaultOptions = {};
        if (options?.size) defaultOptions.size = options.size[0].id;
        if (options?.spice) defaultOptions.spice = options.spice[0].id;
        if (options?.toppings) defaultOptions.toppings = [];

        setSelectedOptions(prev => ({
          ...prev,
          [itemId]: defaultOptions
        }));
      }
    }
  };

  const handleOptionChange = (itemId, category, value) => {
    setSelectedOptions(prev => ({
      ...prev,
      [itemId]: {
        ...prev[itemId],
        [category]: value
      }
    }));
  };

  const handleToppingToggle = (itemId, toppingId) => {
    setSelectedOptions(prev => ({
      ...prev,
      [itemId]: {
        ...prev[itemId],
        toppings: prev[itemId]?.toppings?.includes(toppingId)
          ? prev[itemId].toppings.filter(id => id !== toppingId)
          : [...(prev[itemId]?.toppings || []), toppingId]
      }
    }));
  };

  const calculateItemPrice = (item, options) => {
    let totalPrice = item.price;
    const itemOptions = getItemOptions(item.id);

    if (options && itemOptions) {
      // Size 추가 가격
      if (options.size && itemOptions.size) {
        const sizeOption = itemOptions.size.find(s => s.id === options.size);
        if (sizeOption) totalPrice += sizeOption.price;
      }

      // Toppings 추가 가격
      if (options.toppings && itemOptions.toppings) {
        options.toppings.forEach(toppingId => {
          const topping = itemOptions.toppings.find(t => t.id === toppingId);
          if (topping) totalPrice += topping.price;
        });
      }
    }

    return totalPrice;
  };

  const handleItemClick = (item, e) => {
    // 옵션 버튼 클릭이면 이벤트 중지
    if (e.target.closest('.options-toggle-btn')) {
      return;
    }

    const options = selectedOptions[item.id];
    const itemWithOptions = {
      ...item,
      options,
      finalPrice: calculateItemPrice(item, options)
    };
    onItemSelect(itemWithOptions);
  };

  return (
    <div className="menu-items-grid">
      {items.map(item => {
        const hasOptions = getItemOptions(item.id) !== null;
        const isExpanded = expandedItem === item.id;
        const options = getItemOptions(item.id);
        const currentOptions = selectedOptions[item.id];
        const finalPrice = calculateItemPrice(item, currentOptions);

        return (
          <div 
            key={item.id} 
            className={`menu-item-card ${isExpanded ? 'expanded' : ''}`}
            onClick={(e) => handleItemClick(item, e)}
          >
            <div className="menu-item-image">
              <img 
                src={`https://picsum.photos/200/100?random=${item.id}`}
                alt={item.name}
                className="item-photo"
              />
            </div>
            <div className="menu-item-info">
              <h3 className="item-name">{item.name}</h3>
              <p className="item-description">{item.description}</p>
              <div className="item-price">
                {formatPrice(finalPrice)}
                {finalPrice !== item.price && (
                  <span className="original-price">{formatPrice(item.price)}</span>
                )}
              </div>
            </div>

            {isExpanded && options && (
              <div className="options-panel">
                {/* Size 옵션 */}
                {options.size && (
                  <div className="option-group">
                    <span className="option-label">Size:</span>
                    <div className="option-buttons">
                      {options.size.map(size => (
                        <button
                          key={size.id}
                          className={`option-btn ${currentOptions?.size === size.id ? 'selected' : ''}`}
                          onClick={(e) => {
                            e.stopPropagation();
                            handleOptionChange(item.id, 'size', size.id);
                          }}
                        >
                          {size.name}
                          {size.price > 0 && ` (+${formatPrice(size.price)})`}
                        </button>
                      ))}
                    </div>
                  </div>
                )}

                {/* 맵기 옵션 */}
                {options.spice && (
                  <div className="option-group">
                    <span className="option-label">맵기:</span>
                    <div className="option-buttons">
                      {options.spice.map(spice => (
                        <button
                          key={spice.id}
                          className={`option-btn ${currentOptions?.spice === spice.id ? 'selected' : ''}`}
                          onClick={(e) => {
                            e.stopPropagation();
                            handleOptionChange(item.id, 'spice', spice.id);
                          }}
                        >
                          {spice.name}
                        </button>
                      ))}
                    </div>
                  </div>
                )}

                {/* 토핑 옵션 */}
                {options.toppings && (
                  <div className="option-group">
                    <span className="option-label">토핑:</span>
                    <div className="option-checkboxes">
                      {options.toppings.map(topping => (
                        <label 
                          key={topping.id} 
                          className="checkbox-label"
                          onClick={(e) => e.stopPropagation()}
                        >
                          <input
                            type="checkbox"
                            checked={currentOptions?.toppings?.includes(topping.id) || false}
                            onChange={() => handleToppingToggle(item.id, topping.id)}
                          />
                          <span>{topping.name} (+{formatPrice(topping.price)})</span>
                        </label>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}

            {hasOptions && (
              <button 
                className="options-toggle-btn"
                onClick={(e) => {
                  e.stopPropagation();
                  handleToggleOptions(item.id);
                }}
              >
                {isExpanded ? 'Close Options' : 'Options'}
              </button>
            )}
          </div>
        );
      })}
    </div>
  );
};

export default MenuItems;
